    let reservationId: string | null | undefined = undefined
    if (parsed.data.reservationConfirmationId !== undefined) {
      if (!parsed.data.reservationConfirmationId) {
        reservationId = null
      } else {
        const { data: reservationRow, error: reservationError } = await supabase
          .from('reservations')
          .select('id')
          .eq('property_id', propertyId)
          .eq('confirmation_number', parsed.data.reservationConfirmationId)
          .maybeSingle()
        if (reservationError) {
          throw new Error(`Failed to validate reservation confirmation id: ${reservationError.message}`)
        }
        if (!reservationRow) {
          throw new Error('Reservation confirmation id was not found for this property.')
        }
        reservationId = reservationRow.id
      }
    }

    if (parsed.data.checklistTemplateId) {
      const { data: checklistRow, error: checklistError } = await supabase
        .from('checklist')
        .select('id')
        .eq('property_id', propertyId)
        .eq('id', parsed.data.checklistTemplateId)
        .maybeSingle()
      if (checklistError) {
        throw new Error(`Failed to validate checklist template: ${checklistError.message}`)
      }
      if (!checklistRow) {
        throw new Error('Checklist template was not found for this property.')
      }
    }

    const toIsoOrNull = (value: string | undefined): string | null => {
      if (!value) return null
      const parsedDate = new Date(value)
      if (Number.isNaN(parsedDate.getTime())) {
        throw new Error(`Invalid date/time value: ${value}`)
      }
      return parsedDate.toISOString()
    }

    const queries = new HousekeepingQueries(supabase as unknown as SupabaseClient)
    const housekeepingTask = await queries.updateHousekeepingTask({
      id: housekeepingId,
      propertyId,
      ...(parsed.data.siteId !== undefined ? { siteId: parsed.data.siteId } : {}),
      ...(parsed.data.staffId !== undefined ? { staffId: parsed.data.staffId } : {}),
      ...(parsed.data.title !== undefined ? { title: parsed.data.title } : {}),
      ...(parsed.data.description !== undefined ? { description: parsed.data.description } : {}),
      ...(parsed.data.status !== undefined ? { status: parsed.data.status } : {}),
      ...(parsed.data.priority !== undefined ? { priority: parsed.data.priority } : {}),
      ...(reservationId !== undefined ? { reservationId } : {}),
      ...(parsed.data.checklistTemplateId !== undefined ? { checklistId: parsed.data.checklistTemplateId } : {}),
      ...(parsed.data.startDate !== undefined ? { startDate: toIsoOrNull(parsed.data.startDate) } : {}),
      ...(parsed.data.dueDate !== undefined ? { endDate: toIsoOrNull(parsed.data.dueDate) } : {}),
      ...(parsed.data.checklistItemDone !== undefined
        ? { checklistItemDone: parsed.data.checklistItemDone }
        : {}),
    })

    const siteAvailabilityLogPrefix = '[Housekeeping API v1] PATCH site-availability'
    if (housekeepingTask.status === 'done') {
      console.info(`${siteAvailabilityLogPrefix}: task is done, evaluating site update`, {
        propertyId,
        housekeepingTaskId: housekeepingTask.id,
        siteId: housekeepingTask.site_id,
      })
      const openForSite = await queries.countOpenHousekeepingTasksForSite(propertyId, housekeepingTask.site_id)
      if (openForSite > 0) {
        console.info(`${siteAvailabilityLogPrefix}: skip — other open tasks for this site`, {
          propertyId,
          siteId: housekeepingTask.site_id,
          housekeepingTaskId: housekeepingTask.id,
          openTaskCountForSite: openForSite,
        })
      }
      if (openForSite === 0) {
        // Service role: completing staff may lack sites UPDATE under RLS; property is already authorized above.
        const service = createServiceRoleClient()
        const { data: siteRow, error: siteLoadError } = await service
          .from('sites')
          .select('id, status, site_name, site_number')
          .eq('id', housekeepingTask.site_id)
          .eq('property_id', propertyId)
          .is('deleted_at', null)
          .maybeSingle()

        if (siteLoadError) {
          console.error(`${siteAvailabilityLogPrefix}: failed to load site`, {
            propertyId,
            siteId: housekeepingTask.site_id,
            housekeepingTaskId: housekeepingTask.id,
            siteLoadError,
          })
        } else if (!siteRow) {
          console.warn(`${siteAvailabilityLogPrefix}: skip — no site row (wrong id, property, or deleted)`, {
            propertyId,
            siteId: housekeepingTask.site_id,
            housekeepingTaskId: housekeepingTask.id,
          })
        } else {
          const normalizedStatus = (siteRow.status ?? '').trim().toLowerCase()
          console.info(`${siteAvailabilityLogPrefix}: loaded site`, {
            propertyId,
            siteId: siteRow.id,
            housekeepingTaskId: housekeepingTask.id,
            rawStatus: siteRow.status,
            normalizedStatus,
          })
          if (normalizedStatus === 'housekeeping' || normalizedStatus === 'maintenance') {
            const timestamp = new Date().toISOString()
            const { data: updatedSites, error: siteUpdateError } = await service
              .from('sites')
              .update({ status: 'available', updated_at: timestamp })
              .eq('id', siteRow.id)
              .eq('property_id', propertyId)
              .is('deleted_at', null)
              .select('id')

            if (siteUpdateError) {
              console.error(`${siteAvailabilityLogPrefix}: update failed`, {
                propertyId,
                siteId: siteRow.id,
                housekeepingTaskId: housekeepingTask.id,
                siteUpdateError,
              })
            } else if (!updatedSites?.length) {
              console.error(`${siteAvailabilityLogPrefix}: update matched zero rows`, {
                propertyId,
                siteId: siteRow.id,
                housekeepingTaskId: housekeepingTask.id,
                hint: 'Check site still exists, property_id matches, deleted_at is null',
              })
            } else {
              console.info(`${siteAvailabilityLogPrefix}: site set to available`, {
                propertyId,
                siteId: siteRow.id,
                housekeepingTaskId: housekeepingTask.id,
                previousStatus: siteRow.status,
              })
              if (access.companyId) {
                const siteLabel =
                  siteRow.site_name?.trim() || siteRow.site_number || housekeepingTask.site_id
                await recordActivityLog(
                  service,
                  {
                    companyId: access.companyId,
                    propertyId,
                    action: 'update',
                    resource: 'site',
                    userId: null,
                    details: `Site ${siteLabel} marked available after last housekeeping task was completed.`,
                  },
                  { failOpen: false },
                )
              } else {
                console.warn(`${siteAvailabilityLogPrefix}: no activity log — missing companyId on access`, {
                  propertyId,
                  siteId: siteRow.id,
                })
              }
            }
          } else {
            console.info(`${siteAvailabilityLogPrefix}: skip — site status is not housekeeping or maintenance`, {
              propertyId,
              siteId: siteRow.id,
              housekeepingTaskId: housekeepingTask.id,
              rawStatus: siteRow.status,
              normalizedStatus,
              expectedOneOf: ['housekeeping', 'maintenance'],
            })
          }
        }
      }
    }

    if (access.companyId) {
      const { data: siteRow } = await supabase
        .from('sites')
        .select('site_name, site_number')
        .eq('id', housekeepingTask.site_id)
        .eq('property_id', propertyId)
        .maybeSingle()
      const auditSiteLabel = siteRow?.site_name?.trim() || siteRow?.site_number || housekeepingTask.site_id
      const service = createServiceRoleClient()
      await recordActivityLog(
        service,
        {
          companyId: access.companyId,
          propertyId,
          action: 'update',
          resource: 'housekeeping',
          userId: user.id,
          details: `Updated housekeeping task "${housekeepingTask.title}" for site ${auditSiteLabel}.`,
        },
        { failOpen: false },
      )
    }

    return success({ housekeepingTask }, request)
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Unknown error'
    console.error('[Housekeeping API v1] PATCH error:', err)
    if (
      message === 'Reservation confirmation id was not found for this property.' ||
      message === 'Checklist template was not found for this property.' ||
      message.startsWith('Invalid date/time value:')
    ) {
      return error(ErrorCodes.VALIDATION_ERROR, request, { message })
    }
    return error(ErrorCodes.INTERNAL_ERROR, request, { message })
  }
}

/**
 * DELETE /api/v1/properties/[propertyId]/housekeeping/[housekeepingId]
 *
 * Delete a housekeeping task for the property.
 */

export async function DELETE(
    request: NextRequest,
    { params }: { params: Promise<{ propertyId: string; housekeepingId: string }> }
) {
    try {
        const { propertyId, housekeepingId } = await params
        const supabase = await createClient()

        const {
            data: { user },
            error: authError,
        } = await supabase.auth.getUser()

        if (authError || !user) {
            return error(ErrorCodes.AUTH_001, request)
        }

        const access = await requirePropertyAccess(supabase, user.id, {
            propertyId,
            permission: 'housekeeping.reassign',
        })
        if (isDenied(access)) return access

        const actionAccess = await resolveModuleActionAccess({
          supabase: supabase as any,
          propertyId,
          userId: user.id,
          moduleKey: 'housekeeping',
          actions: ['delete'],
          fallbackForCategory: housekeepingFallbackForCategory,
        })
        if (!actionAccess.delete) {
          return error(
            ErrorCodes.AUTH_002.code,
            'You do not have permission to delete housekeeping tasks.',
            ErrorCodes.AUTH_002.status,
            request,
          )
        }

        const { data: existingTask } = await supabase
          .from('housekeeping_tasks')
          .select('title, site_id')
          .eq('id', housekeepingId)
          .eq('property_id', propertyId)
          .maybeSingle()

        const queries = new HousekeepingQueries(supabase as unknown as SupabaseClient)
        await queries.deleteHousekeepingTask({ id: housekeepingId, propertyId })

        if (access.companyId) {
          let auditSiteLabel = existingTask?.site_id ?? 'unknown site'
          if (existingTask?.site_id) {
            const { data: siteRow } = await supabase
              .from('sites')
              .select('site_name, site_number')
              .eq('id', existingTask.site_id)
              .eq('property_id', propertyId)
              .maybeSingle()
            auditSiteLabel = siteRow?.site_name?.trim() || siteRow?.site_number || existingTask.site_id
          }

          const deletedTaskLabel = existingTask?.title ?? housekeepingId
          const service = createServiceRoleClient()
          await recordActivityLog(
            service,
            {
              companyId: access.companyId,
              propertyId,
              action: 'delete',
              resource: 'housekeeping',
              userId: user.id,
              details: `Deleted housekeeping task "${deletedTaskLabel}" for site ${auditSiteLabel}.`,
            },
            { failOpen: false },
          )
        }

        return success({ deleted: true }, request)
    } catch (err) {
        const message = err instanceof Error ? err.message : 'Unknown error'
        console.error('[Housekeeping API v1] DELETE error:', err)
        return error(ErrorCodes.INTERNAL_ERROR, request, { message })
    }
}

"use client"

import { useCallback, useEffect, useMemo, useState } from "react"
import { createClient } from "@/lib/supabase/client"
import {
  HousekeepingQueries,
  parseChecklistTemplateLines,
  type PropertyChecklistListItem,
} from "@/lib/dashboard/housekeeping/housekeeping-queries"
import type { SupabaseClient } from "@supabase/supabase-js"
import {
  EditChecklistDialog,
  type EditChecklistTemplateInput,
} from "../housekeeping-dialog.tsx/edit-checklist-dialog"
import { DeleteChecklistConfirmationDialog } from "../housekeeping-dialog.tsx/delete-checklist-confirmation-dialog"
import { ChecklistDetailsDialog } from "../housekeeping-dialog.tsx/checklist-details-dialog"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { useToast } from "@/hooks/use-toast"
import { formatShortDate } from "@/lib/utils"
import { ClipboardList, Eye, MoreHorizontal, Pencil, Trash2 } from "lucide-react"
import { Pagination } from "@/components/ui/pagination"
import { PageSizeSelector } from "@/components/ui/page-size-selector"

function countChecklistItems(item: PropertyChecklistListItem["item"]): number {
  return parseChecklistTemplateLines(item).length
}

type HousekeepingChecklistPanelProps = {
  propertyId: string
  /** Increment to refetch after creating or updating checklists elsewhere. */
  refreshKey?: number
  canEditChecklist?: boolean
  canDeleteChecklist?: boolean
}

export function HousekeepingChecklistPanel({
  propertyId,
  refreshKey = 0,
  canEditChecklist = false,
  canDeleteChecklist = false,
}: HousekeepingChecklistPanelProps) {
  const { toast } = useToast()
  const [rows, setRows] = useState<PropertyChecklistListItem[]>([])
  const [loading, setLoading] = useState(true)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const [checklistPendingDelete, setChecklistPendingDelete] = useState<PropertyChecklistListItem | null>(null)
  const [editingChecklist, setEditingChecklist] = useState<PropertyChecklistListItem | null>(null)
  const [viewingChecklist, setViewingChecklist] = useState<PropertyChecklistListItem | null>(null)
  const [isSavingChecklistEdit, setIsSavingChecklistEdit] = useState(false)
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(10)

  const load = useCallback(async () => {
    setLoading(true)
    setErrorMessage(null)
    try {
      const supabase = createClient()
      const queries = new HousekeepingQueries(supabase as unknown as SupabaseClient)
      const list = await queries.listPropertyChecklists(propertyId)
      setRows(list)
    } catch (loadError) {
      const message =
        loadError instanceof Error ? loadError.message : "Something went wrong while loading checklists."
      setErrorMessage(message)
      setRows([])
    } finally {
      setLoading(false)
    }
  }, [propertyId])

  useEffect(() => {
    void load()
  }, [load, refreshKey])

  const total = rows.length
  const totalPages = Math.max(1, Math.ceil(total / perPage))
  const pageRows = useMemo(() => {
    const start = (page - 1) * perPage
    return rows.slice(start, start + perPage)
  }, [rows, page, perPage])

  useEffect(() => {
    setPage((current) => Math.min(current, totalPages))
  }, [rows, totalPages])

  const startIndex = total === 0 ? 0 : (page - 1) * perPage + 1
  const endIndex = total === 0 ? 0 : Math.min(page * perPage, total)

  const goToPage = useCallback(
    (next: number) => {
      const clamped = Math.max(1, Math.min(next, totalPages))
      setPage(clamped)
    },
    [totalPages],
  )

  const handleSaveChecklistEdit = async (input: EditChecklistTemplateInput) => {
    setIsSavingChecklistEdit(true)
    try {
      const response = await fetch(
        `/api/v1/properties/${propertyId}/housekeeping/checklists/${input.checklistId}`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            name: input.name,
            description: input.description,
            items: input.items.map((row) => ({
              id: row.id,
              label: row.label,
              notes: row.notes,
            })),
          }),
        },
      )
      const payload = await response.json()
      if (!response.ok || !payload?.success) {
        const message =
          payload?.error?.details?.message ??
          payload?.error?.message ??
          "Failed to update checklist template."
        throw new Error(message)
      }
      toast({
        title: "Checklist updated",
        description: "Your changes have been saved.",
      })
      setEditingChecklist(null)
      await load()
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to update checklist template."
      toast({
        title: "Unable to save",
        description: message,
        variant: "destructive",
      })
    } finally {
      setIsSavingChecklistEdit(false)
    }
  }

  if (loading) {
    return (
      <div className="rounded-lg border border-border/80 bg-card px-4 py-10 text-center text-sm text-muted-foreground">
        Loading checklists…
      </div>
    )
  }

  if (errorMessage) {
    return (
      <div className="rounded-lg border border-destructive/30 bg-destructive/5 px-4 py-6 text-center text-sm text-destructive">
        {errorMessage}
      </div>
    )
  }

  if (rows.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center gap-3 rounded-lg border border-dashed border-border/80 bg-card px-6 py-14 text-center">
        <ClipboardList className="h-10 w-10 text-muted-foreground" aria-hidden />
        <div className="space-y-1">
          <p className="text-sm font-medium text-foreground">No checklists yet</p>
          <p className="max-w-md text-sm text-muted-foreground">
            Property checklists will appear here once they are added for this property.
          </p>
        </div>
      </div>
    )
  }

  return (
    <>
      <DeleteChecklistConfirmationDialog
        open={canDeleteChecklist && checklistPendingDelete !== null}
        onOpenChange={(next) => {
          if (!next) setChecklistPendingDelete(null)
        }}
        propertyId={propertyId}
        checklist={
          checklistPendingDelete
            ? { id: checklistPendingDelete.id, name: checklistPendingDelete.name }
            : null
        }
        onDeleted={() => {
          void load()
        }}
      />
      <EditChecklistDialog
        open={canEditChecklist && editingChecklist !== null}
        onOpenChange={(next) => {
          if (!next) setEditingChecklist(null)
        }}
        checklist={editingChecklist}
        isSubmitting={isSavingChecklistEdit}
        onSubmit={handleSaveChecklistEdit}
      />
      <ChecklistDetailsDialog
        open={viewingChecklist !== null}
        onOpenChange={(next) => {
          if (!next) setViewingChecklist(null)
        }}
        checklist={viewingChecklist}
      />
      <div className="border border-border/80 bg-card/50">
      <Table className="min-w-[1200px] table-fixed text-xs">
        <colgroup>
          <col style={{ width: "24%" }} />
          <col style={{ width: "36%" }} />
          <col style={{ width: "10%" }} />
          <col style={{ width: "16%" }} />
          <col style={{ width: "14%" }} />
        </colgroup>
        <TableHeader className="sticky top-0 z-10 bg-red-50 dark:bg-red-950/30 uppercase">
          <TableRow className="h-8 hover:bg-transparent data-[state=selected]:bg-transparent">
            <TableHead className="px-4 py-2 text-left font-medium text-black/90 dark:text-white/90">Name</TableHead>
            <TableHead className="px-4 py-2 text-left font-medium text-black/90 dark:text-white/90">
              Description
            </TableHead>
            <TableHead className="px-3 py-2 text-right font-medium text-black/90 dark:text-white/90">Items</TableHead>
            <TableHead className="px-3 py-2 text-right font-medium text-black/90 dark:text-white/90">Created</TableHead>
            <TableHead className="px-3 py-2 text-right font-medium text-black/90 dark:text-white/90">Actions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {pageRows.map((row) => {
            const itemCount = countChecklistItems(row.item)
            const createdLabel = formatShortDate(row.created_at)
            return (
              <TableRow
                key={row.id}
                className="border-border/80 hover:bg-muted/30 data-[state=selected]:bg-muted/30"
              >
                <TableCell className="px-3 py-2 align-top">
                  <div className="break-words text-sm font-semibold leading-snug text-foreground">{row.name}</div>
                </TableCell>
                <TableCell className="px-3 py-2 align-top">
                  <div className="break-words text-sm leading-snug text-muted-foreground">
                    {row.description?.trim() ? row.description.trim() : "—"}
                  </div>
                </TableCell>
                <TableCell className="px-3 py-2 text-right align-middle text-sm tabular-nums text-muted-foreground">
                  {itemCount}
                </TableCell>
                <TableCell className="px-3 py-2 text-right align-middle text-sm text-muted-foreground whitespace-nowrap">
                  {createdLabel}
                </TableCell>
                <TableCell className="px-3 py-2 align-middle">
                  <div className="flex items-center justify-end">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 p-0"
                          aria-label={`Checklist actions for ${row.name}`}
                        >
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-48">
                        <DropdownMenuItem onClick={() => setViewingChecklist(row)}>
                          <Eye className="mr-2 h-4 w-4" />
                          View checklist
                        </DropdownMenuItem>
                        {canEditChecklist ? (
                          <DropdownMenuItem onClick={() => setEditingChecklist(row)}>
                            <Pencil className="mr-2 h-4 w-4" />
                            Edit checklist
                          </DropdownMenuItem>
                        ) : null}
                        {canDeleteChecklist ? (
                          <DropdownMenuItem
                            onClick={() => setChecklistPendingDelete(row)}
                            className="text-red-600 focus:text-red-600"
                          >
                            <Trash2 className="mr-2 h-4 w-4" />
                            Delete checklist
                          </DropdownMenuItem>
                        ) : null}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                </TableCell>
              </TableRow>
            )
          })}
        </TableBody>
      </Table>
      </div>
      <div className="mt-3 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex w-full flex-col items-center gap-2 text-xs text-muted-foreground sm:w-auto sm:flex-row sm:items-center sm:gap-4">
          <div>
            Showing{" "}
            <span className="font-medium">
              {startIndex}–{endIndex}
            </span>{" "}
            of <span className="font-medium">{total}</span> checklists
          </div>
          <PageSizeSelector
            value={perPage}
            onChange={(next) => {
              setPerPage(next)
              setPage(1)
            }}
            disabled={loading}
          />
        </div>
        <div className="flex w-full justify-center sm:w-auto sm:justify-end">
          <Pagination
            currentPage={page}
            totalPages={totalPages}
            onPageChange={goToPage}
            disabled={loading}
            windowSize={2}
          />
        </div>
      </div>
    </>
  )
}

