    return { view: true, create: false, update: false, delete: false }
  }
  return { view: false, create: false, update: false, delete: false }
}

async function getHousekeepingPageOptions(
  supabase: Awaited<ReturnType<typeof createClient>>,
  propertyId: string,
): Promise<{ siteOptions: SelectOption[]; assigneeOptions: SelectOption[]; checklistOptions: SelectOption[] }> {
  // All non-deleted sites: tasks can reference a site after turnover (e.g. status becomes available);
  // restricting to housekeeping-only would leave Edit Task with no matching SelectItem and an empty Site field.
  const { data: sites } = await supabase
    .from("sites")
    .select("id, site_number, site_name")
    .eq("property_id", propertyId)
    .is("deleted_at", null)
    .order("site_number", { ascending: true })

  const siteOptions = (sites ?? []).map((site) => ({
    id: site.id as string,
    label: (site.site_name as string | null)?.trim() || (site.site_number as string),
  }))

  const { data: staffCategories } = await supabase
    .from("property_role_categories")
    .select("id, name")
    .eq("property_id", propertyId)
    .eq("role", "staff")

  const housekeepingCategoryIds = (staffCategories ?? [])
    .filter((category) => category.name.trim().toLowerCase() === "housekeeping")
    .map((category) => category.id as string)

  let assigneeOptions: SelectOption[] = []
  if (housekeepingCategoryIds.length > 0) {
    const { data: housekeepingStaff } = await supabase
      .from("property_staff")
      .select("id, user_id")
      .eq("property_id", propertyId)
      .eq("role", "staff")
      .eq("status", "active")
      .overlaps("role_category_id", housekeepingCategoryIds)

    const adminClient = createServiceRoleClient()
    assigneeOptions = (
      await Promise.all(
        (housekeepingStaff ?? []).map(async (staffRow) => {
          if (!staffRow.user_id) return null
          const { data, error } = await adminClient.auth.admin.getUserById(staffRow.user_id)
          if (error || !data.user) return null

          const metadata = (data.user.user_metadata ?? {}) as Record<string, unknown>
          const fullName =
            typeof metadata.full_name === "string" ? metadata.full_name.trim() : ""
          const firstName =
            typeof metadata.first_name === "string" ? metadata.first_name.trim() : ""
          const lastName =
            typeof metadata.last_name === "string" ? metadata.last_name.trim() : ""
          const fallbackName = [firstName, lastName].filter(Boolean).join(" ").trim()
          const displayName = fullName || fallbackName || data.user.email || "Staff member"

          return {
            id: staffRow.id as string,
            label: displayName,
          }
        }),
      )
    )
      .filter((option): option is SelectOption => Boolean(option))
      .sort((a, b) => a.label.localeCompare(b.label))
  }

  const { data: checklists } = await supabase
    .from("checklist")
    .select("id, name")
    .eq("property_id", propertyId)
    .order("name", { ascending: true })

  const checklistOptions = (checklists ?? []).map((row) => ({
    id: row.id as string,
    label: (row.name as string).trim(),
  }))

  return {
    siteOptions,
    assigneeOptions,
    checklistOptions,
  }
}

export default async function HousekeepingPage({ params }: PageProps) {
  const { propertyId } = await params
  const property = await getPropertyForUser(propertyId)
  if (!property) redirect("/auth/login")

  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) redirect("/auth/login")

  const navVisibility = await resolveDashboardNavVisibility(supabase, propertyId, user.id)
  if (!navVisibility.housekeepingNavVisible) {
    redirect(`/dashboard/${propertyId}/access-denied`)
  }

  const [{ siteOptions, assigneeOptions, checklistOptions }, taskActionAccess, propertyAccess] =
    await Promise.all([
      getHousekeepingPageOptions(supabase, propertyId),
      resolveModuleActionAccess({
        supabase,
        propertyId,
        userId: user.id,
        moduleKey: "housekeeping",
        actions: ["create", "update", "delete"],
        fallbackForCategory: housekeepingFallbackForCategory,
      }),
      resolveUserPropertyAccess(supabase, propertyId, user.id),
    ])

  const showAssigneeFilter = propertyAccess?.isElevated === true

  return (
    <HousekeepingPageContent
      propertyId={propertyId}
      propertyName={property.name}
      siteOptions={siteOptions}
      assigneeOptions={assigneeOptions}
      checklistOptions={checklistOptions}
      canCreateTask={taskActionAccess.create === true}
      canEditTask={taskActionAccess.update === true}
      canDeleteTask={taskActionAccess.delete === true}
      showAssigneeFilter={showAssigneeFilter}
    />
  )
}

import type { SupabaseClient } from '@supabase/supabase-js'
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { success, error } from '@/lib/api/response'
import { ErrorCodes } from '@/lib/api/errors'
import { createServiceRoleClient } from '@/lib/supabase/service-role'
import { recordActivityLog } from '@/shared/activity-log/record-activity-log'
import { resolveModuleActionAccess } from '@/lib/dashboard/module-action-access'
import { requirePropertyAccess, isDenied } from '@/lib/rbac'
import { HousekeepingQueries, type ListHousekeepingTasksFilters } from '@/lib/dashboard/housekeeping/housekeeping-queries'
import {
  CreateHousekeepingTaskRequestSchema,
  ListHousekeepingTasksQuerySchema,
} from '@/types/api/v1/schemas/housekeeping'

function housekeepingFallbackForCategory(
  role: 'owner' | 'admin' | 'manager' | 'staff',
  categoryName: string,
): Record<string, boolean> {
  if (role === 'owner' || role === 'admin') return { view: true, create: true, update: true, delete: true }
  const category = categoryName.trim().toLowerCase()
  if (role === 'manager' && category === 'housekeeping') {
    return { view: true, create: true, update: true, delete: true }
  }
  if (role === 'staff' && category === 'housekeeping') {
    return { view: true, create: false, update: false, delete: false }
  }
  return { view: false, create: false, update: false, delete: false }
}

/**
 * GET /api/v1/properties/[propertyId]/housekeeping
 *
 * List housekeeping tasks for the property.
 *
 * Query parameters (all optional):
 * - search: free-text match on title, description, or site name/number
 * - siteId: UUID of site
 * - assigneeId: property_staff UUID, or "unassigned" (elevated roles only; staff are always scoped to their own row)
 * - status: pending | in_progress | done
 * - priority: low | medium | high | urgent
 * - page: positive integer (default 1)
 * - per_page: 1–100 (default 10)
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ propertyId: string }> },
) {
  try {
    const { propertyId } = await params
    const supabase = await createClient()

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser()

    if (authError || !user) {
      return error(ErrorCodes.AUTH_001, request)
    }

    const access = await requirePropertyAccess(supabase, user.id, {
      propertyId,
      permission: 'housekeeping.view_assigned',
    })
    if (isDenied(access)) return access

    let propertyStaffId: string | null = null
    if (!access.isElevated) {
      const { data: staffRow, error: staffLookupError } = await supabase
        .from('property_staff')
        .select('id')
        .eq('property_id', propertyId)
        .eq('user_id', user.id)
        .in('status', ['active', 'pending'])
        .maybeSingle()

      if (staffLookupError) {
        console.error('[Housekeeping API v1] GET: property_staff lookup failed', staffLookupError)
        return error(ErrorCodes.INTERNAL_ERROR, request, { message: staffLookupError.message })
      }
      if (!staffRow?.id) {
        return error(ErrorCodes.VALIDATION_ERROR, request, {
          message: 'No active staff assignment found for this property.',
        })
      }
      propertyStaffId = staffRow.id as string
    }

    const { searchParams } = new URL(request.url)
    const queryRaw = {
      search: searchParams.get('search') ?? undefined,
      siteId: searchParams.get('siteId') ?? undefined,
      assigneeId: searchParams.get('assigneeId') ?? undefined,
      status: searchParams.get('status') ?? undefined,
      priority: searchParams.get('priority') ?? undefined,
      page: searchParams.get('page') ?? undefined,
      per_page: searchParams.get('per_page') ?? undefined,
    }

    const parsed = ListHousekeepingTasksQuerySchema.safeParse(queryRaw)
    if (!parsed.success) {
      return error(ErrorCodes.VALIDATION_ERROR, request, {
        errors: parsed.error.format(),
      })
    }

    const data = parsed.data
    const listFilters: ListHousekeepingTasksFilters = {}
    if (data.search !== undefined) {
      listFilters.search = data.search
    }
    if (data.siteId !== undefined) {
      listFilters.siteId = data.siteId
    }
    if (access.isElevated) {
      if (data.assigneeId !== undefined) {
        listFilters.assigneeId = data.assigneeId
      }
    } else if (propertyStaffId) {
      listFilters.assigneeId = propertyStaffId
    }
    if (data.status !== undefined) {
      listFilters.status = data.status
    }
    if (data.priority !== undefined) {
      listFilters.priority = data.priority
    }

    const queries = new HousekeepingQueries(supabase as unknown as SupabaseClient)
    const [listResult, openTaskCount] = await Promise.all([
      queries.listHousekeepingTasks(
        propertyId,
        Object.keys(listFilters).length > 0 ? listFilters : undefined,
        { page: data.page, perPage: data.per_page },
      ),
      queries.countOpenHousekeepingTasks(
        propertyId,
        propertyStaffId ? { assigneeId: propertyStaffId } : undefined,
      ),
    ])
    return success(
      {
        tasks: listResult.tasks,
        total: listResult.total,
        page: data.page,
        per_page: data.per_page,
        openTaskCount,
      },
      request,
    )
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Unknown error'
    console.error('[Housekeeping API v1] GET error:', err)
    return error(ErrorCodes.INTERNAL_ERROR, request, { message })
  }
}

/**
 * POST /api/v1/properties/[propertyId]/housekeeping
 *
 * Create a manual housekeeping task for the property.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ propertyId: string }> },
) {
    try {
        const { propertyId } = await params
        const supabase = await createClient()

        const {
        data: { user },
        error: authError,
        } = await supabase.auth.getUser()

        if (authError || !user) {
        return error(ErrorCodes.AUTH_001, request)
        }

        const access = await requirePropertyAccess(supabase, user.id, {
        propertyId,
        permission: 'housekeeping.create_manual',
        })
        if (isDenied(access)) return access

        const actionAccess = await resolveModuleActionAccess({
          supabase: supabase as any,
          propertyId,
          userId: user.id,
          moduleKey: 'housekeeping',
          actions: ['create'],
          fallbackForCategory: housekeepingFallbackForCategory,
        })
        if (!actionAccess.create) {
          return error(
            ErrorCodes.AUTH_002.code,
            'You do not have permission to create housekeeping tasks.',
            ErrorCodes.AUTH_002.status,
            request,
          )
        }

        const body = await request.json()
        const parsed = CreateHousekeepingTaskRequestSchema.safeParse(body)

        if (!parsed.success) {
          return error(ErrorCodes.VALIDATION_ERROR, request, {
              errors: parsed.error.format(),
          })
        }

        let reservationId: string | null = null
        if (parsed.data.reservationConfirmationId) {
          const { data: reservationRow, error: reservationError } = await supabase
            .from('reservations')
            .select('id')
            .eq('property_id', propertyId)
            .eq('confirmation_number', parsed.data.reservationConfirmationId)
            .maybeSingle()

          if (reservationError) {
            throw new Error(`Failed to validate reservation confirmation id: ${reservationError.message}`)
          }
          if (!reservationRow) {
            throw new Error('Reservation confirmation id was not found for this property.')
          }
          reservationId = reservationRow.id
        }

        if (parsed.data.checklistTemplateId) {
          const { data: checklistRow, error: checklistError } = await supabase
            .from('checklist')
            .select('id')
            .eq('property_id', propertyId)
            .eq('id', parsed.data.checklistTemplateId)
            .maybeSingle()
          if (checklistError) {
            throw new Error(`Failed to validate checklist template: ${checklistError.message}`)
          }
          if (!checklistRow) {
            throw new Error('Checklist template was not found for this property.')
          }
        }

        const toIsoOrNull = (value: string | undefined): string | null => {
          if (!value) return null
          const parsedDate = new Date(value)
          if (Number.isNaN(parsedDate.getTime())) {
            throw new Error(`Invalid date/time value: ${value}`)
          }
          return parsedDate.toISOString()
        }

        const queries = new HousekeepingQueries(supabase as unknown as SupabaseClient)
        const housekeepingTask = await queries.createHousekeepingTask({
          propertyId,
          siteId: parsed.data.siteId,
          staffId: parsed.data.staffId ?? null,
          title: parsed.data.title,
          description: parsed.data.description ?? null,
          createdBy: user.id,
          ...(parsed.data.status !== undefined ? { status: parsed.data.status } : {}),
          ...(parsed.data.priority !== undefined ? { priority: parsed.data.priority } : {}),
          ...(reservationId !== null ? { reservationId } : {}),
          ...(parsed.data.checklistTemplateId !== undefined ? { checklistId: parsed.data.checklistTemplateId } : {}),
          ...(parsed.data.startDate !== undefined ? { startDate: toIsoOrNull(parsed.data.startDate) } : {}),
          ...(parsed.data.dueDate !== undefined ? { endDate: toIsoOrNull(parsed.data.dueDate) } : {}),
          ...(parsed.data.checklistItemDone !== undefined
            ? { checklistItemDone: parsed.data.checklistItemDone }
            : {}),
        })

        if (access.companyId) {
          const { data: siteRow } = await supabase
            .from('sites')
            .select('site_name, site_number')
            .eq('id', housekeepingTask.site_id)
            .eq('property_id', propertyId)
            .maybeSingle()
          const auditSiteLabel = siteRow?.site_name?.trim() || siteRow?.site_number || housekeepingTask.site_id
          const service = createServiceRoleClient()
          await recordActivityLog(
            service,
            {
              companyId: access.companyId,
              propertyId,
              action: 'create',
              resource: 'housekeeping',
              userId: user.id,
              details: `Created housekeeping task "${housekeepingTask.title}" for site ${auditSiteLabel}.`,
            },
            { failOpen: false },
          )
        }

        return success({ housekeepingTask }, request)
    } catch (err) {
        const message = err instanceof Error ? err.message : 'Unknown error'
        console.error('[Housekeeping API v1] POST error:', err)

        if (
          message === 'Site not found for this property' ||
          message === 'Assignee not found for this property' ||
          message === 'Reservation confirmation id was not found for this property.' ||
          message === 'Checklist template was not found for this property.' ||
          message.startsWith('Invalid date/time value:')
        ) {
        return error(ErrorCodes.VALIDATION_ERROR, request, { message })
        }

        return error(ErrorCodes.INTERNAL_ERROR, request, { message })
    }
}

import type { createClient } from "@/lib/supabase/server"
import { resolveUserPropertyAccess } from "@/lib/rbac/resolve-access"

type UiRole = "owner" | "admin" | "manager" | "staff"

type FallbackResolver = (role: UiRole, categoryName: string) => Record<string, boolean>

type ResolveModuleActionAccessInput = {
  supabase: Awaited<ReturnType<typeof createClient>>
  propertyId: string
  userId: string
  moduleKey: string
  actions: readonly string[]
  fallbackForCategory: FallbackResolver
}

function toUiRole(rawRole: string | null): UiRole {
  const normalized = (rawRole ?? "").toLowerCase()
  if (normalized === "owner") return "owner"
  if (normalized === "admin" || normalized === "property_admin") return "admin"
  if (normalized === "manager") return "manager"
  return "staff"
}

function normalizeAccessPayload(
  raw: unknown,
): { moduleAccessControl?: Record<string, Record<string, boolean>> } | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null
  const maybe = raw as { moduleAccessControl?: unknown }
  if (
    !maybe.moduleAccessControl ||
    typeof maybe.moduleAccessControl !== "object" ||
    Array.isArray(maybe.moduleAccessControl)
  ) {
    return null
  }
  return { moduleAccessControl: maybe.moduleAccessControl as Record<string, Record<string, boolean>> }
}

function buildEmptyActions(actions: readonly string[]): Record<string, boolean> {
  return Object.fromEntries(actions.map((action) => [action, false]))
}

function buildFullActions(actions: readonly string[]): Record<string, boolean> {
  return Object.fromEntries(actions.map((action) => [action, true]))
}

export async function resolveModuleActionAccess({
  supabase,
  propertyId,
  userId,
  moduleKey,
  actions,
  fallbackForCategory,
}: ResolveModuleActionAccessInput): Promise<Record<string, boolean>> {
  const resolvedAccess = await resolveUserPropertyAccess(supabase, propertyId, userId)
  if (resolvedAccess?.isOwner) {
    return buildFullActions(actions)
  }

  const { data: staffAssignment } = await supabase
    .from("property_staff")
    .select("role, role_category_id")
    .eq("property_id", propertyId)
    .eq("user_id", userId)
    .in("status", ["active", "pending"])
    .maybeSingle()

  // Elevated users with no explicit staff assignment keep full module actions.
  if (!staffAssignment?.role && resolvedAccess?.isElevated) {
    return buildFullActions(actions)
  }

  const role = toUiRole(typeof staffAssignment?.role === "string" ? staffAssignment.role : null)
  if (role === "owner") {
    return buildFullActions(actions)
  }

  const categoryIds = staffAssignment?.role_category_id ?? []
  if (!Array.isArray(categoryIds) || categoryIds.length === 0) {
    return role === "admin" ? buildFullActions(actions) : buildEmptyActions(actions)
  }

  const { data: categoryRows } = await supabase
    .from("property_role_categories")
    .select("name, access")
    .eq("property_id", propertyId)
    .eq("role", role)
    .in("id", categoryIds)

  const rows = categoryRows ?? []
  if (rows.length === 0) {
    return role === "admin" ? buildFullActions(actions) : buildEmptyActions(actions)
  }

  const resolved = buildEmptyActions(actions)
  for (const row of rows) {
    const fallback = fallbackForCategory(role, row.name ?? "")
    const access = normalizeAccessPayload(row.access)
    const moduleAccess = access?.moduleAccessControl?.[moduleKey] ?? null

    for (const action of actions) {
      const hasExplicitToggle = moduleAccess != null && Object.prototype.hasOwnProperty.call(moduleAccess, action)
      const allowedForRow = hasExplicitToggle
        ? moduleAccess?.[action] === true
        : fallback[action] === true
      resolved[action] = resolved[action] || allowedForRow
    }
  }

  return resolved
}

/**
 * Core access resolver for Camp-OS RBAC.
 *
 * Resolves the current user's role, company, and staff categories for a property
 * in a single pass. Follows the proven `verifyPropertyAccess()` pattern from
 * staff-management-queries.ts.
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import type { EffectiveRole } from './roles'
import { toEffectiveRole, isDbRole } from './roles'
import type { StaffCategory } from './staff-categories'
import { normaliseCategories } from './staff-categories'

// ─── Resolved access type ──────────────────────────────────────────────────────

export interface ResolvedAccess {
  userId: string
  propertyId: string
  companyId: string | null
  /** Normalised role for application logic (property_admin → admin). */
  role: EffectiveRole | null
  /** Original raw role from the database. */
  rawRole: string | null
  /** Staff categories assigned to the user. Empty if none or non-staff. */
  categories: StaffCategory[]
  /** True when user is the company owner (companies.owner_id === userId). */
  isOwner: boolean
  /** True for owner, admin, or manager roles. */
  isElevated: boolean
  /** True when user has a platform_admin flag in user_metadata. */
  isPlatformAdmin: boolean
}

// ─── Category name resolution ──────────────────────────────────────────────────

/**
 * Resolve category names from `property_role_categories` UUIDs.
 *
 * The `property_staff.role_category_id` column stores an array of UUIDs
 * referencing `property_role_categories.id`. This function fetches the
 * corresponding category names and normalises them.
 */
async function resolveCategoryNames(
  supabase: SupabaseClient,
  categoryIds: string[] | null | undefined,
  propertyId: string,
): Promise<StaffCategory[]> {
  if (!categoryIds || categoryIds.length === 0) return []

  const { data } = await supabase
    .from('property_role_categories')
    .select('name')
    .eq('property_id', propertyId)
    .in('id', categoryIds)

  if (!data || data.length === 0) return []

  const normalizedNames = data.map((row) => {
    const rawName = typeof row.name === 'string' ? row.name.trim().toLowerCase() : ''
    return rawName.replace(/[\s-]+/g, '_')
  })

  return normaliseCategories(normalizedNames)
}

// ─── Resolver ──────────────────────────────────────────────────────────────────

/**
 * Resolve a user's access to a property.
 *
 * Returns `null` when the user has no access to the property.
 * Throws no errors — callers should treat `null` as "not found / 404".
 */
export async function resolveUserPropertyAccess(
  supabase: SupabaseClient,
  propertyId: string,
  userId: string,
): Promise<ResolvedAccess | null> {
  // 1. Get property → company
  const { data: property } = await supabase
    .from('properties')
    .select('company_id, owner_id')
    .eq('id', propertyId)
    .maybeSingle()

  if (!property) return null

  // 2. Check if user is the company owner
  const companyId: string | null = property.company_id
  const isOwner = property.owner_id === userId

  if (isOwner) {
    return {
      userId,
      propertyId,
      companyId,
      role: 'owner',
      rawRole: 'owner',
      categories: [],
      isOwner: true,
      isElevated: true,
      isPlatformAdmin: false,
    }
  }

  // 3. Check company ownership via companies table
  if (companyId) {
    const { data: company } = await supabase
      .from('companies')
      .select('owner_id')
      .eq('id', companyId)
      .maybeSingle()

    if (company?.owner_id === userId) {
      return {
        userId,
        propertyId,
        companyId,
        role: 'owner',
        rawRole: 'owner',
        categories: [],
        isOwner: true,
        isElevated: true,
        isPlatformAdmin: false,
      }
    }
  }

  // 4. Check property_staff assignment
  const { data: staffRow } = await supabase
    .from('property_staff')
    .select('role, role_category_id')
    .eq('property_id', propertyId)
    .eq('user_id', userId)
    .in('status', ['active', 'pending'])
    .maybeSingle()

  if (!staffRow?.role) return null

  const rawRole = staffRow.role as string
  const effectiveRole = isDbRole(rawRole) ? toEffectiveRole(rawRole) : 'staff'
  const categories = await resolveCategoryNames(supabase, staffRow.role_category_id, propertyId)

  // Backward compatibility: staff with no categories get 'all' category
  // This ensures existing staff assignments aren't suddenly locked out
  const resolvedCategories = effectiveRole === 'staff' && categories.length === 0
    ? ['all' as StaffCategory]
    : categories

  return {
    userId,
    propertyId,
    companyId,
    role: effectiveRole,
    rawRole,
    categories: resolvedCategories,
    isOwner: false,
    isElevated: effectiveRole !== 'staff',
    isPlatformAdmin: false,
  }
}

/**
 * Resolve user access or throw a structured error.
 *
 * This is a convenience wrapper for use in route handlers where you want
 * to short-circuit with a 404 if the user has no access.
 *
 * For platform admin detection, pass `userMetadata` and this function will
 * set `isPlatformAdmin: true` when `userMetadata.user_type === 'platform_admin'`.
 */
export async function resolveUserPropertyAccessOrThrow(
  supabase: SupabaseClient,
  propertyId: string,
  userId: string,
  userMetadata?: Record<string, unknown> | null,
): Promise<ResolvedAccess> {
  const access = await resolveUserPropertyAccess(supabase, propertyId, userId)

  if (!access) {
    throw new AccessDeniedError('Property not found or access denied', 404)
  }

  // Check platform admin flag
  if (userMetadata && typeof userMetadata.user_type === 'string' && userMetadata.user_type === 'platform_admin') {
    access.isPlatformAdmin = true
  }

  return access
}

// ─── Error type ────────────────────────────────────────────────────────────────

export class AccessDeniedError extends Error {
  constructor(
    message: string,
    public readonly statusCode: number = 403,
  ) {
    super(message)
    this.name = 'AccessDeniedError'
  }
}

/**
 * Route guard helpers for Camp-OS RBAC.
 *
 * These functions are designed for use in Next.js API route handlers.
 * They return `NextResponse` on denial (so the caller can `return` it directly)
 * or a `ResolvedAccess` object on success.
 */

import { NextResponse } from 'next/server'
import type { SupabaseClient } from '@supabase/supabase-js'
import type { EffectiveRole } from './roles'
import type { PermissionKey } from './permissions'
import type { StaffCategory } from './staff-categories'
import {
  resolveUserPropertyAccess,
  type ResolvedAccess,
} from './resolve-access'
import { hasPermission } from './permissions'
import { staffHasPermission } from './staff-categories'

// ─── Requirements interface ────────────────────────────────────────────────────

export interface AccessRequirements {
  propertyId: string
  /** Minimum effective role required. Checked before permission. */
  minimumRole?: EffectiveRole
  /** Specific permission key required. */
  permission?: PermissionKey
  /** Require at least one of these categories (staff role only). */
  anyCategory?: StaffCategory[]
  /** Any of these roles — alternative to minimumRole for multi-role paths. */
  anyOfRoles?: EffectiveRole[]
}

// ─── Guard result type ─────────────────────────────────────────────────────────

type GuardResult =
  | { access: ResolvedAccess; denied: false }
  | { denied: true; response: NextResponse }

function deny(status: number, message: string): GuardResult {
  return {
    denied: true,
    response: NextResponse.json(
      { success: false, error: { code: `AUTH_${status === 404 ? '004' : '003'}`, message } },
      { status },
    ),
  }
}

// ─── Main guard function ───────────────────────────────────────────────────────

/**
 * Check property access and optional permission/category requirements.
 *
 * Usage in route handlers:
 * ```ts
 * const result = await checkPropertyAccess(supabase, userId, {
 *   propertyId,
 *   minimumRole: 'admin',
 *   permission: 'financial.refund',
 * })
 * if (result.denied) return result.response
 * const { access } = result
 * ```
 */
export async function checkPropertyAccess(
  supabase: SupabaseClient,
  userId: string,
  requirements: AccessRequirements,
): Promise<GuardResult> {
  const { propertyId, minimumRole, permission, anyCategory, anyOfRoles } = requirements

  // Resolve base access
  const access = await resolveUserPropertyAccess(supabase, propertyId, userId)
  if (!access) {
    return deny(404, 'Property not found or access denied')
  }

  // Platform admin bypasses everything
  if (access.isPlatformAdmin) {
    return { access, denied: false }
  }

  const role = access.role

  // If no specific role required, just having access is enough
  if (!minimumRole && !anyOfRoles && !permission) {
    return { access, denied: false }
  }

  // Check minimum role
  if (minimumRole && role) {
    const ROLE_RANK: Record<EffectiveRole, number> = {
      owner: 40, admin: 30, manager: 20, staff: 10,
    }
    if ((ROLE_RANK[role] ?? 0) < (ROLE_RANK[minimumRole] ?? 0)) {
      return deny(403, 'Insufficient role for this operation')
    }
  }

  // Check anyOfRoles (alternative role check)
  if (anyOfRoles && role && !anyOfRoles.includes(role)) {
    return deny(403, 'Insufficient role for this operation')
  }

  // Check permission
  if (permission && role) {
    // First check the role's built-in permissions (for manager+)
    if (hasPermission(role, permission)) {
      return { access, denied: false }
    }

    // For staff role, check if any category grants this permission
    if (role === 'staff') {
      if (staffHasPermission(access.categories, permission)) {
        return { access, denied: false }
      }
    }

    return deny(403, 'Permission denied for this operation')
  }

  // Check category requirement
  if (anyCategory && anyCategory.length > 0 && role === 'staff') {
    const hasMatch = access.categories.includes('all') ||
      anyCategory.some((cat) => access.categories.includes(cat))
    if (!hasMatch) {
      return deny(403, 'Category access required for this operation')
    }
  }

  return { access, denied: false }
}

// ─── Convenience wrappers ──────────────────────────────────────────────────────

/**
 * Verify the user can access a property (any role, owner OR active staff).
 * Returns access on success or a 404 NextResponse on denial.
 */
export async function requirePropertyMembership(
  supabase: SupabaseClient,
  userId: string,
  propertyId: string,
): Promise<ResolvedAccess | NextResponse> {
  const result = await checkPropertyAccess(supabase, userId, { propertyId })
  if (result.denied) return result.response
  return result.access
}

/**
 * Verify the user meets role/permission/category requirements for an operation.
 */
export async function requirePropertyAccess(
  supabase: SupabaseClient,
  userId: string,
  requirements: AccessRequirements,
): Promise<ResolvedAccess | NextResponse> {
  const result = await checkPropertyAccess(supabase, userId, requirements)
  if (result.denied) return result.response
  return result.access
}

/**
 * Type guard to check if the result of requirePropertyAccess / requirePropertyMembership
 * is a NextResponse (denied) or ResolvedAccess (granted).
 */
export function isDenied(result: ResolvedAccess | NextResponse): result is NextResponse {
  return result instanceof NextResponse
}

